func matchesString(c storage.EvaluationConstraint, v string) bool {
	switch c.Operator {
	case flipt.OpEmpty:
		return len(strings.TrimSpace(v)) == 0
	case flipt.OpNotEmpty:
		return len(strings.TrimSpace(v)) != 0
	case flipt.OpIsOneOf, flipt.OpIsNotOneOf:
		var values []string
		matched := false
		if err := json.Unmarshal([]byte(c.Value), &values); err == nil && values != nil {
			var raw []json.RawMessage
			if err := json.Unmarshal([]byte(c.Value), &raw); err == nil {
				valid := true
				for _, item := range raw {
					if string(item) == "null" {
						valid = false
						break
					}
				}
				for _, value := range values {
					if valid && value == v {
						matched = true
						break
					}
				}
			}
		}
		return matched != (c.Operator == flipt.OpIsNotOneOf)
	}

	if v == "" {
		return false
	}

	value := c.Value

	switch c.Operator {
	case flipt.OpEQ:
		return value == v
	case flipt.OpNEQ:
		return value != v
	case flipt.OpPrefix:
		return strings.HasPrefix(strings.TrimSpace(v), value)
	case flipt.OpSuffix:
		return strings.HasSuffix(strings.TrimSpace(v), value)
	}

	return false
}

